function gas(id,g,s,d,o){platform(g,8,5);const tank=mesh(g,new T.BoxGeometry(3.2,2.4,2.2),mat(0x8dc5e8,{transparent:true,opacity:.07,depthWrite:false}),0,1.4,0),edges=new T.LineSegments(new T.EdgesGeometry(tank.geometry),new T.LineBasicMaterial({color:0x71a5c9}));edges.position.copy(tank.position);g.add(edges);const piston=box(g,3.1,.12,2.1,C.metal,0,2.5,0),heater=box(g,3.3,.18,2.3,C.orange,0,.15,0),count=80,particles=new T.InstancedMesh(new T.SphereGeometry(.052,10,8),mat(C.cyan),count),dummy=new T.Object3D();g.add(particles);const needle=gauge(g,2.8,1.5,.5,o),l=label(g,'',V(0,3.7,0),o);return(s,d)=>{const height=id==='isobaric'?.65+d.volume*.3:2.4;piston.visible=id==='isobaric';piston.position.y=.2+height;tank.scale.y=height/2.4;tank.position.y=.2+height/2;edges.scale.copy(tank.scale);edges.position.copy(tank.position);const v=Math.sqrt(s.temp/300)*(id==='kinetic'?Math.sqrt(28/s.molar):1),fold=x=>{const a=((x%2)+2)%2;return a>1?2-a:a};for(let j=0;j<count;j++){dummy.position.set((fold(j*.618+tNow(s)*v*.41)-.5)*2.95,.3+fold(j*.317+tNow(s)*v*.27)*Math.max(.2,height-.2),(fold(j*.414+tNow(s)*v*.36)-.5)*1.95);dummy.updateMatrix();particles.setMatrixAt(j,dummy.matrix);}particles.instanceMatrix.needsUpdate=true;particles.material.color.copy(colorTemp(s.temp/5));heater.material.emissive.setHex(C.orange);heater.material.emissiveIntensity=Math.max(0,(s.temp-200)/700);needle.rotation.z=-clamp((d.pressure||s.pressure||s.temp/4)/300,0,1)*2.4;setText(l,id==='isobaric'?`${d.volume.toFixed(2)} L · p không đổi`:id==='isochoric'?`${d.pressure.toFixed(1)} kPa · V không đổi`:`v RMS = ${d.rms.toFixed(0)} m/s`);};}
