function electric(id,g,s,d,o){platform(g,8,5);const l=label(g,'',V(0,3.2,0),o);if(id==='resistivity'){const wire=cylinder(g,.14,4,C.orange,0,1.1,0);wire.rotation.z=Math.PI/2;const ends=[box(g,.3,.4,.5,C.dark,-2.3,.6,0),box(g,.3,.4,.5,C.dark,2.3,.6,0)];return(s,d)=>{wire.scale.y=.35+s.length*.15;wire.scale.x=wire.scale.z=Math.sqrt(s.area/.2);wire.material.color.setHSL(.09-s.rho*.06,.5,.57);setText(l,`R = ${d.resistance.toFixed(3)} Ω`);};}
if(id==='bridge'){const points=[V(0,2.6,0),V(-2,1.3,0),V(2,1.3,0),V(0,.3,0)];[[0,1],[1,3],[0,2],[2,3]].forEach(([a,b],j)=>{line(g,[points[a],points[b]],C.blue);const r=cylinder(g,.16,.65,j===3?C.purple:0xd8aa78,...points[a].clone().lerp(points[b],.5).toArray());r.quaternion.setFromUnitVectors(V(0,1,0),points[b].clone().sub(points[a]).normalize());label(g,`R${j+1}`,r.position.clone().add(V(0,.38,.1)),o);});line(g,[points[1],points[2]],C.green);const needle=gauge(g,0,1.3,.1,o);return(s,d)=>{needle.rotation.z=-clamp(d.difference/5,-1,1);setText(l,Math.abs(d.difference)<1e-8?'Cầu cân bằng':`U AB = ${d.difference.toFixed(3)} V`);};}
const source=box(g,1.2,1.4,.7,C.dark,-2.2,1,0),load=cylinder(g,.24,1.1,0xe4b374,1.7,1.0,0);load.rotation.z=Math.PI/2;line(g,[V(-2.2,1.1,0),V(-2.2,1.1,-1.1),V(2,1.1,-1.1),V(2,1.1,0),V(1.7,1.1,0)],C.blue);line(g,[V(-2.2,.6,0),V(-2.2,.6,1.1),V(2,.6,1.1),V(2,1.1,0)],C.orange);const flow=new T.InstancedMesh(new T.SphereGeometry(.044,10,8),mat(C.orange,{emissive:C.orange,emissiveIntensity:.4}),14),probe=new T.Object3D();g.add(flow);const screen=label(g,'',V(-2.2,2.1,0),o),indicator=sphere(g,.15,C.orange,1.7,1.6,0);return(s,d)=>{flow.visible=Math.abs(d.i||0)>1e-9;for(let j=0;j<14;j++){const f=((((s.t||0)*.25*Math.sign(d.i)+j/14)%1)+1)%1;probe.position.set(-2+4*f,1.13,-1.1);probe.updateMatrix();flow.setMatrixAt(j,probe.matrix);}flow.instanceMatrix.needsUpdate=true;setText(screen,id==='ac'?`${d.voltage.toFixed(2)} V`:`${s.emf.toFixed(1)} V · r ${s.internalR} Ω`);indicator.material.emissive.setHex(C.orange);indicator.material.emissiveIntensity=Math.abs(d.i||0)*.4;setText(l,id==='ac'?`U RMS = ${d.rms.toFixed(2)} V`:`U hai cực = ${d.terminal.toFixed(2)} V`);};}
function electromagnet(id,g,s,d,o){platform(g,8,5);const l=label(g,'',V(0,3.25,0),o);if(id==='lorentz'){const ball=sphere(g,.16,C.orange),trail=line(g,Array.from({length:161},()=>V()),C.blue),velocity=arrow(g,V(),V(1,0,0),C.green),force=arrow(g,V(),V(0,-1,0),C.purple);for(let x=-3;x<=3;x++)for(let y=.3;y<3;y+=.8){const dot=sphere(g,.03,0xb2c5dc,x,y,-.1);}return(s,d,c)=>{const scale=d.radius===null?.2:2/Math.max(2,d.radius);ball.position.set(d.x*scale,2+d.y*scale,0);ball.material.color.setHex(s.charge<0?C.blue:C.orange);updateLine(trail,Array.from({length:161},(_,j)=>{const q=evaluateDiscovery('lorentz',{...s,t:s.t*j/160});return V(q.x*scale,2+q.y*scale,0)}));trail.visible=c.switches?.trajectory!==false;velocity.position.copy(ball.position);velocity.setDirection(V(d.vx,d.vy,0).normalize());force.position.copy(ball.position);force.setDirection(V(Math.sign(s.charge)*d.vy,-Math.sign(s.charge)*d.vx,0).normalize());velocity.visible=c.switches?.vectors!==false;force.visible=velocity.visible&&s.charge!==0;setText(l,d.radius===null?'q = 0 · Đi thẳng':`r = ${d.radius.toFixed(2)} m`);};}
if(id==='solenoid'){const coils=new T.Group();g.add(coils);for(let j=0;j<20;j++){const m=mesh(coils,new T.TorusGeometry(.65,.035,10,48),mat(C.orange),-1.7+j*3.4/19,1.3,0);m.rotation.y=Math.PI/2;}const arrows=Array.from({length:3},(_,j)=>arrow(g,V(-1.4,1.3,(j-1)*.3),V(1,0,0),C.blue,2.8));label(g,'Lõi không khí',V(0,.35,1),o);return(s,d,c)=>{coils.scale.x=.4+s.length;coils.children.forEach((m,j)=>m.visible=j<Math.max(2,Math.round(s.turns/50)));arrows.forEach(a=>{a.visible=Math.abs(s.i)>1e-8&&c.switches?.vectors!==false;a.setDirection(V(Math.sign(s.i)||1,0,0));a.position.x=s.i<0?1.4:-1.4;});setText(l,`B = ${(d.b*1000).toFixed(3)} mT`);};}
box(g,4.6,2.1,.45,0x8d9bae,0,1.2,0);box(g,3.0,1.15,.55,0xf0f5fb,0,1.2,0);const coils=[new T.Group(),new T.Group()];coils.forEach((c,j)=>{g.add(c);for(let k=0;k<12;k++){const ring=mesh(c,new T.TorusGeometry(.55,.04,8,40),mat(j?C.blue:C.orange),-1.7+j*3.4,.6+k*.1,0);ring.rotation.x=Math.PI/2;}});label(g,'Sơ cấp',V(-2,2.85,0),o);label(g,'Thứ cấp',V(2,2.85,0),o);const flux=arrow(g,V(-.9,2.38,.28),V(1,0,0),C.green,1.8);return(s,d)=>{const phase=Math.cos(2*Math.PI*(s.t||0));flux.setDirection(V(Math.sign(phase)||1,0,0));flux.position.x=phase<0?.9:-.9;flux.setLength(.2+1.6*Math.abs(phase),.12,.06);coils.forEach((c,j)=>c.children.forEach((m,k)=>{m.visible=k<Math.max(2,Math.round((j?s.n2:s.n1)/500*12));m.material.emissive.setHex(j?C.blue:C.orange);m.material.emissiveIntensity=.12+.10*Math.abs(phase);}));setText(l,`U₂ RMS = ${d.u2.toFixed(1)} V`);};}
export function buildDiscoveryModel(id,s,d,o={}){const group=new T.Group();let update;switch(id){case 'freefall':update=freefall(group,s,d,o);break;case 'friction':case 'work':case 'impulse':update=movingBox(id,group,s,d,o);break;case 'buoyancy':case 'pressure':update=fluid(id,group,s,d,o);break;case 'reflection':case 'refraction':case 'tir':update=premiumRayOptics(id,group,s,d,o);break;case 'lens':case 'mirror':update=imageOptics(id,group,s,d,o);break;case 'prism':update=prism(group,s,d,o);break;case 'young':case 'diffraction':update=fringes(id,group,s,d,o);break;case 'polarization':update=polarization(group,s,d,o);break;case 'thermalexpansion':case 'calorimetry':case 'phasechange':case 'heattransfer':case 'firstlaw':update=thermal(id,group,s,d,o);break;case 'isobaric':case 'isochoric':case 'kinetic':update=gas(id,group,s,d,o);break;case 'resistivity':case 'internalresistance':case 'bridge':case 'ac':update=electric(id,group,s,d,o);break;case 'solenoid':case 'lorentz':case 'transformer':update=electromagnet(id,group,s,d,o);break;default:throw Error('Unknown scene '+id);}update(s,d,o.config||{});return {group,update};}
